contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        // record owner before
        address before = c.owner();
        bool reverted;
        bool ret;
        // attempt to call setOwner; capture revert and return value
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }
        address after = c.owner();
        // General rule: if call succeeded (did not revert) then it must have returned true and owner==newOwner;
        // if it reverted then owner must be unchanged.
        assert((!reverted && ret && after == newOwner) || (reverted && after == before));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address possibleAdmin) public payable {
        require(true);
        // The contract C was deployed before this test with its constructor setting owner = deployer.
        // In this execution the deployer of C is the address that deployed the fresh c instance
        // which (per the harness) is the same as address(this) at C's deployment time. We check
        // that the public owner getter returns some address; the invariant we assert is that
        // c.owner() is equal to address of the deployer of C. The only deployer observable here
        // is the current owner returned by c.owner(), so we assert that calling setOwner by
        // a non-admin reverts and does not change owner (this both observes admin constraint and
        // links owner before/after). However, the problem disallows repeating the admin rule.
        // Instead we assert a weaker universally true property: the owner getter is never the zero address
        // immediately after construction. Since c is freshly deployed by the harness, owner() must be non-zero.

        // Read owner
        address beforeOwner = c.owner();

        // Attempt to call setOwner as this contract; it may revert or succeed depending on admin value.
        bool reverted;
        try c.setOwner(possibleAdmin) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();

        // General rule: the stored owner is never the zero address (both before and after attempt).
        // This asserts that owner() != address(0) holds for all inputs and regardless of revert.
        assert(beforeOwner != address(0) && afterOwner != address(0));
    }
    receive() external payable { }
}
